/// <reference types="vite/client" />

interface ImportMetaEnv {
  /** Build-time fallback for API_URL (runtime /config.js wins). */
  readonly VITE_API_URL?: string;
  readonly VITE_MAP_TILES_URL?: string;
  readonly VITE_MAP_TILES_TYPE?: string;
  readonly VITE_MAP_ATTRIBUTION?: string;
  readonly VITE_SHOW_EXTERNAL_MAP_LINKS?: string;
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}

/**
 * Runtime configuration written by /config.js (generated by the container
 * entrypoint from environment variables, see public/config.js).
 */
interface AppRuntimeConfig {
  API_URL?: string;
  MAP_TILES_URL?: string;
  MAP_TILES_TYPE?: 'pmtiles' | 'xyz' | 'none' | string;
  MAP_ATTRIBUTION?: string;
  SHOW_EXTERNAL_MAP_LINKS?: boolean | string;
}

interface Window {
  __APP_CONFIG__?: AppRuntimeConfig;
}
